// Generates docs/COMMANDS.md from the operation catalog and message bundles.
// `node scripts/commands-doc.mjs --check` fails when the committed file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { operations } from '../lib/contracts.js';

const target = new URL('../docs/COMMANDS.md', import.meta.url);
const summary = (bundle) =>
  readFileSync(new URL(`../messages/${bundle}.md`, import.meta.url), 'utf8')
    .match(/^# summary\n(.+)$/m)[1]
    .trim();

const lines = [
  '# Command reference',
  '',
  'Generated by `npm run docs` from the operation catalog and message bundles. Run `sf ace schema --json` for structural body schemas and `sf ace COMMAND --help` for full flag help. Every command supports Salesforce JSON output.',
  '',
  '## sf ace setup',
  '',
  summary('setup'),
  '',
  'Requires an existing administrator `--target-org`, an active `--username`, and an existing ACTIVE `--agent-id` for verification. `--dry-run` returns a local plan; execute with `--allow-write` and confirmation. CI uses `--no-prompt --confirm FINGERPRINT`. Supports `--app-name`, `--alias`, `--contact-email`, and permanent `--key-dir`. See [headless setup](../README.md#headless-setup).',
  '',
  '## sf ace schema',
  '',
  summary('schema'),
  '',
  'Offline helper; makes no network request. `--command "ace session create"` narrows the output to one operation.',
];

for (const op of operations) {
  const base = op.surface === 'configuration' ? '/services/data/v{version}/ssot/agentic' : '/api/v1/agentic';
  const rows = op.parameters.map((p) => [`--${p.name}`, `${p.location}: \`${p.wire}\``, p.required ? 'Yes' : 'No']);
  if (op.command === 'ace session list') rows.push(['--source', 'local: `index` or `conversation`', 'No']);
  lines.push(
    '',
    `## sf ${op.command}`,
    '',
    summary(op.command.replaceAll(' ', '.')),
    '',
    `\`${op.method} ${base}${op.path}\``,
  );
  if (rows.length)
    lines.push(
      '',
      '| Flag | Wire location/name | Required |',
      '| --- | --- | --- |',
      ...rows.map(([flag, wire, required]) => `| \`${flag}\` | ${wire} | ${required} |`),
    );
  if (op.command === 'ace session list')
    lines.push(
      '',
      '`--source index` (default) uses the native session index. `--source conversation` projects session summaries from the conversation graph, including closed sessions the index omits. It supports status and id/startTime/status fields, rejects participant/time-range filters, and preserves graph pagination.',
    );
  if (op.body)
    lines.push(
      '',
      `Requires \`--body-file\` containing the published JSON body. Inspect it with \`sf ace schema --command "${op.command}" --json\`.`,
    );
  if (op.method !== 'GET')
    lines.push(
      '',
      'Requires `--allow-write` and interactive confirmation, or `--no-prompt --confirm FINGERPRINT` after dry-run review.',
    );
}

const output = `${lines.join('\n')}\n`;
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== output) {
    console.error('docs/COMMANDS.md is stale. Run npm run docs.');
    process.exit(1);
  }
} else writeFileSync(target, output);
